        error = posix_acl_update_mode(inode, &inode->i_mode, NULL);
        if (error)
            return error;
    } else if (type == ACL_TYPE_DEFAULT) {
        if (S_ISDIR(inode->i_mode))
            error = posix_acl_update_mode(inode, &inode->i_mode, NULL);
